// The test for src/host's inteng menus (inteng_menus.h; inteng_menus.cpp is generated by tools/make-inteng-menus.js): every screen's bar
// loads into the menu bar, the tables are inteng's (facts measured from docs/inteng/inteng-menus.json on 2026-11-15), and every item either
// works or says why it doesn't. Written 2026-11-15 by Melanikus (Dietrich) for AVP_OpenInteng (A6, the all-menus build). AVP_OpenInteng's
// own code: see License.txt, "AVP_OpenInteng's own code".
//
// It runs none of the editor. Each check's words say what it proves. The program gives back a non-zero result if any check failed.

#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <string>

#include "inteng_menus.h"
#include "menu_bar.h"

using namespace host;

static int checksFailed = 0;

static void Check(bool good, std::string const &what)
{
	printf("  %s  %s\n", good ? "ok" : "FAILED", what.c_str());

	if (!good)
	{
		checksFailed++;
	}
}

// Whether a text is these words: a null text is never any words (so a missing text fails its check, never crashes it)
static bool Is(const char *text, const char *words)
{
	return text && strcmp(text, words) == 0;
}

// A screen's bar as the editor will make it (A6-1b(iii)): each menu's items with their tags' words, loaded into the menu bar
static bool LoadsIntoTheBar(const IntengScreen &screen)
{
	static ui::Menu menus[ui::kMenuMostMenus];
	static ui::MenuItem items[ui::kMenuMostMenus][ui::kMenuMostItems];

	if (screen.count == 0 || screen.count > ui::kMenuMostMenus)
	{
		return false;
	}

	for (size_t m = 0; m < screen.count; m++)
	{
		const IntengMenu &menu = screen.menus[m];

		if (menu.count > ui::kMenuMostItems)
		{
			return false;
		}

		for (size_t i = 0; i < menu.count; i++)
		{
			items[m][i].name = menu.items[i].name;
			items[m][i].keys = 0;
			items[m][i].action = menu.items[i].action;
			items[m][i].tag = IntengMenus_TagWords(menu.items[i].tag);
		}

		menus[m].title = menu.title;
		menus[m].items = items[m];
		menus[m].count = menu.count;
	}

	ui::MenuBar bar;

	return bar.Load(menus, screen.count);
}

// The first item of a screen with these words, or null
static const IntengItem *ItemNamed(size_t screen, const char *name)
{
	for (size_t m = 0; m < kIntengScreens[screen].count; m++)
	{
		for (size_t i = 0; i < kIntengScreens[screen].menus[m].count; i++)
		{
			if (strcmp(kIntengScreens[screen].menus[m].items[i].name, name) == 0)
			{
				return &kIntengScreens[screen].menus[m].items[i];
			}
		}
	}

	return nullptr;
}

static bool MenusAre(size_t screen, const char *const *titles, const size_t *counts, size_t count)
{
	bool same = kIntengScreens[screen].count == count;

	for (size_t m = 0; same && m < count; m++)
	{
		same = strcmp(kIntengScreens[screen].menus[m].title, titles[m]) == 0 && kIntengScreens[screen].menus[m].count == counts[m];
	}

	return same;
}

static void TestTheScreens()
{
	puts("Every screen:");

	Check(kIntengScreenCount == 23, "inteng's 16 tables and 7 stand-ins are 23 screens");
	Check(strcmp(kIntengScreens[kIntengHub].name, "Construction") == 0 && strcmp(kIntengScreens[kIntengHub].table, "0x5ced30") == 0,
		"the hub is Construction, inteng's table at 0x5ced30");

	bool allLoad = true;
	bool room = true;
	std::string first;

	for (size_t s = 0; s < kIntengScreenCount; s++)
	{
		if (!LoadsIntoTheBar(kIntengScreens[s]))
		{
			allLoad = false;
			first = first.empty() ? kIntengScreens[s].name : first;
		}

		room = room && kIntengScreens[s].count + 2 <= ui::kMenuMostMenus;
	}

	Check(allLoad, "every screen's bar loads into the menu bar: its words, tags and numbers pass the bar's checks" + (first.empty() ? std::string() : " (not: " + first + ")"));
	Check(room, "every screen leaves room on its bar for the editor's own two menus");
}

static void TestTheTablesAreInteng()
{
	puts("The tables are inteng's:");

	const char *const hubTitles[] = { "File", "Mode", "Object", "Shape", "Miscellaneous", "Options" };
	// File holds inteng's 4 and the owner's Save, second (Melanikus 2026-11-16, "Let's put a save on the hub": named, not inteng's)
	size_t const hubCounts[] = { 5, 11, 10, 3, 4, 3 };

	Check(MenusAre(0, hubTitles, hubCounts, 6), "construction's bar is inteng's with the owner's Save: File 5 (Quit, Save, Write C, Write Asc, Write Asc doors closed), Mode 11, Object 10, Shape 3, Miscellaneous 4, Options 3 records (a cascade's item and its rows each one)");

	IntengMenu const *const file = &kIntengScreens[0].menus[0];

	Check(file && file->count == 5 && strcmp(file->items[0].name, "Quit") == 0 && strcmp(file->items[1].name, "Save") == 0 && file->items[1].work == IntengWork::SaveCopy &&
		file->items[1].command == 0 && strcmp(file->items[2].name, "Write C File") == 0, "the hub's Save is second, after Quit, does Object Placement's Save (SaveCopy), and has no inteng command");
	Check(kIntengScreens[0].menus[1].count == 11 && strcmp(kIntengScreens[0].menus[1].items[8].name, "Strategy Data") == 0 && kIntengScreens[0].menus[1].items[8].level == 1 &&
	      strcmp(kIntengScreens[0].menus[1].items[9].name, "Normal") == 0 && kIntengScreens[0].menus[1].items[9].level == 2 &&
	      strcmp(kIntengScreens[0].menus[1].items[10].name, "No Textures") == 0 && kIntengScreens[0].menus[1].items[10].level == 2,
		"a CASCADE (BAR-10, inteng's kind 1 with kind-2 records): Mode's Strategy Data is level 1, its Normal and No Textures level 2 right after it, each with its own words");
	Check(kIntengScreens[0].menus[1].items[9].work == IntengWork::ToScreen && kIntengScreens[0].menus[1].items[10].work == IntengWork::ToScreenNoTextures &&
	      kIntengScreens[0].menus[1].items[8].work == IntengWork::None,
		"its rows do what they did (Strategy Data's screen, with and without textures); the cascade's own item does nothing (BAR-12)");

	const char *const placementTitles[] = { "Mode", "Object", "Create", "Alt Locations", "Misc" };
	size_t const placementCounts[] = { 3, 10, 8, 6, 7 };

	Check(MenusAre(6, placementTitles, placementCounts, 5), "object placement's bar is inteng's: Mode 3, Object 10, Create 8, Alt Locations 6, Misc 7 records (a cascade's item and its rows each one)");
	Check(kIntengScreens[4].count == 9, "module linking's bar has its 9 titles");

	bool blankGone = ItemNamed(4, "") == nullptr;
	bool links = kIntengScreens[5].count == 8;

	for (size_t m = 0; links && m < 8; m++)
	{
		links = kIntengScreens[5].menus[m].count == 1 && strcmp(kIntengScreens[5].menus[m].items[0].name, kIntengScreens[5].menus[m].title) == 0;
	}

	Check(blankGone, "module linking's blank line is left out");
	Check(links, "the links table's 8 titles, each with a command and nothing under it, are each a menu of one item with its words");

	const IntengItem *flagged[2] = { nullptr, nullptr };
	size_t found = 0;

	for (size_t m = 0; m < kIntengScreens[10].count; m++)
	{
		for (size_t i = 0; i < kIntengScreens[10].menus[m].count; i++)
		{
			if (kIntengScreens[10].menus[m].items[i].command == 0x1fa5 && found < 2)
			{
				flagged[found++] = &kIntengScreens[10].menus[m].items[i];
			}
		}
	}

	Check(found == 2 && flagged[0]->action != flagged[1]->action,
		"the cutscene table uses command 0x1fa5 twice, and its two items still have numbers of their own");
}

static void TestEveryItemWorksOrSaysWhy()
{
	puts("Every item works or says why not:");

	const IntengItem *const quit = ItemNamed(0, "Quit");
	const IntengItem *const placement = ItemNamed(0, "Object Placement");
	const IntengItem *const texture = ItemNamed(0, "Texture Map");

	Check(quit && quit->tag == IntengTag::None && quit->work == IntengWork::Quit, "construction's Quit works: it closes the editor");
	Check(placement && placement->work == IntengWork::ToScreen && placement->toScreen == 6 && placement->tag == IntengTag::None,
		"construction's Object Placement works: it goes to object placement's bar");
	Check(texture && texture->tag == IntengTag::None && texture->work == IntengWork::ToScreen && texture->toScreen == 22,
		"Texture Map starts its mode: it goes to the Texture Map screen (the mode so far = entering and leaving, polygon select / deselect; the texture commands are [wip])");

	// Track Editing (Edit Track 0x36 on Object Placement goes to the code-built Track Editing screen, whose pages carry inteng's own command numbers, track-menu-pairs.md)
	{
		size_t track = kIntengScreenCount;

		for (size_t s = 0; s < kIntengScreenCount; s++)
		{
			if (strcmp(kIntengScreens[s].name, "Track Editing") == 0)
			{
				track = s;
			}
		}

		const IntengItem *const editTrack = ItemNamed(6, "Edit Track");
		const IntengItem *found[6] = {};
		int const wanted[6] = { 0x518, 0x517, 0x514, 0x51c, 0x520, 0x51e };

		if (track < kIntengScreenCount)
		{
			for (size_t p = 0; p < kIntengScreens[track].pageCount; p++)
			{
				for (size_t m = 0; m < kIntengScreens[track].pages[p].count; m++)
				{
					for (size_t i = 0; i < kIntengScreens[track].pages[p].menus[m].count; i++)
					{
						for (int w = 0; w < 6; w++)
						{
							if (kIntengScreens[track].pages[p].menus[m].items[i].command == wanted[w] && !found[w])
							{
								found[w] = &kIntengScreens[track].pages[p].menus[m].items[i];
							}
						}
					}
				}
			}
		}

		Check(track < kIntengScreenCount && strcmp(kIntengScreens[track].table, "0x5e6e98") == 0, "Track Editing is a code-built screen on inteng's table 0x5e6e98");
		Check(editTrack && editTrack->work == IntengWork::ToScreen && editTrack->toScreen == track && editTrack->command == 0x36 && editTrack->tag == IntengTag::None,
			"Object Placement's Edit Track (0x36) goes to the Track Editing screen");
		Check(found[0] && found[0]->work == IntengWork::TrackEdit && found[1] && found[1]->work == IntengWork::TrackEdit && found[2] && found[2]->work == IntengWork::TrackEdit && found[3] && found[4] && found[4]->work == IntengWork::TrackEdit && found[5] && found[5]->work == IntengWork::TrackEdit,
			"the Track Editing pages' items work and carry inteng's command numbers (Add Section 0x518, Finish End Pos Edit 0x517, Play Track 0x514, Stop Track Edit 0x51c, Delete Track 0x520, Stop Pivot Edit 0x51e)");
	}

	bool sound = true;
	bool targets = true;
	bool noAvp = true;
	bool standIns = true;

	for (size_t s = 0; s < kIntengScreenCount; s++)
	{
		for (size_t m = 0; m < kIntengScreens[s].count; m++)
		{
			for (size_t i = 0; i < kIntengScreens[s].menus[m].count; i++)
			{
				const IntengItem &item = kIntengScreens[s].menus[m].items[i];

				// a cascade's own item (level 1, BAR-12) does nothing and says nothing: its rows do and say
				sound = sound && (item.level == 1 ? item.tag == IntengTag::None && item.work == IntengWork::None :
				                  ((item.tag == IntengTag::None) == (item.work != IntengWork::None)) && (item.tag == IntengTag::None) == (IntengMenus_Why(item.tag) == nullptr));
				targets = targets && (item.work != IntengWork::ToScreen || (item.toScreen > 0 && (size_t)item.toScreen < kIntengScreenCount));

				if (s == 7 || s == 9 || s == 10)
				{
					noAvp = noAvp && (item.level == 1 || item.tag == IntengTag::NoAvp || (item.work == IntengWork::ExitMode && strcmp(item.name, "Exit") == 0));
				}
			}
		}

		if (s >= 16)
		{
			const IntengScreen &screen = kIntengScreens[s];

			if (screen.pageCount > 0)
			{
				// A code-built screen (inteng's own menus, docs/inteng/inteng-menus-built.json): its first bar is row 1 page 0, its second row 2 page 0
				// when there is one, both are among its pages, and Exit is on the first bar, working
				bool first = false, second = screen.secondRow == nullptr, exit = false;

				for (size_t p = 0; p < screen.pageCount; p++)
				{
					first = first || (screen.pages[p].row == 1 && screen.pages[p].page == 0 && screen.pages[p].menus == screen.menus && screen.pages[p].count == screen.count);
					second = second || (screen.pages[p].row == 2 && screen.pages[p].page == 0 && screen.pages[p].menus == screen.secondRow && screen.pages[p].count == screen.secondRowCount);
				}

				for (size_t m = 0; m < screen.count; m++)
				{
					for (size_t i = 0; i < screen.menus[m].count; i++)
					{
						exit = exit || ((screen.menus[m].items[i].work == IntengWork::ToHub || screen.menus[m].items[i].work == IntengWork::ExitMode) && strcmp(screen.menus[m].items[i].name, "Exit") == 0);
					}
				}

				standIns = standIns && first && second && exit;
			}
			else if (screen.count == 1)
			{
				// A stand-in with no menus of its own: Mode, with Exit and the line saying its menu is being mapped
				const IntengMenu &menu = screen.menus[0];

				standIns = standIns && menu.count == 2 && menu.items[0].work == IntengWork::ExitMode
					&& menu.items[1].tag != IntengTag::None && strcmp(menu.items[1].name, "Menu being mapped from inteng") == 0;
			}
			else
			{
				// A stand-in with menus of its own (the words inteng's strings give): the last is Mode, with Exit alone, or its own menus
				// hold inteng's own Exit, an item named Exit that does something (Acoustic's page 7: Mode > Exit, 0xa, back to Object
				// Placement); every other item says it isn't done yet, or does something
				const IntengMenu &mode = screen.menus[screen.count - 1];
				bool ownExit = false;

				for (size_t m = 0; m < screen.count; m++)
				{
					for (size_t i = 0; i < screen.menus[m].count; i++)
					{
						ownExit = ownExit || (strcmp(screen.menus[m].items[i].name, "Exit") == 0 && screen.menus[m].items[i].work != IntengWork::None);
					}
				}

				bool const oursLast = mode.count == 1 && mode.items[0].work == IntengWork::ExitMode && strcmp(mode.title, "Mode") == 0;

				standIns = standIns && (oursLast || ownExit);

				for (size_t m = 0; m < (oursLast ? screen.count - 1 : screen.count); m++)
				{
					for (size_t i = 0; i < screen.menus[m].count; i++)
					{
						// an item says it isn't done yet, or does something (tag and work agree, checked above for every item)
						standIns = standIns && ((screen.menus[m].items[i].tag != IntengTag::None) != (screen.menus[m].items[i].work != IntengWork::None));
					}
				}
			}
		}
	}

	Check(sound, "an item that does something has no tag, and every other item has one, with words to say why");
	Check(targets, "every item that goes to a screen goes to one that's there, never the hub itself");
	Check(noAvp, "every item of the other game's placement, camera tracks and cutscenes is tagged no AvP, but for its Exit");
	Check(standIns, "every stand-in's bar is Mode: Exit, which works, and the item saying its menu is being mapped");
	Check(Is(IntengMenus_TagWords(IntengTag::Wip), " [wip]") && Is(IntengMenus_TagWords(IntengTag::Blender), " [Blender]")
		&& Is(IntengMenus_TagWords(IntengTag::NoAvp), " [no AvP]") && Is(IntengMenus_TagWords(IntengTag::Unfinished), " [unfinished in inteng]") && IntengMenus_TagWords(IntengTag::None) == nullptr,
		"the tags' words are \" [wip]\", \" [Blender]\" and \" [no AvP]\", and an item that works has none");
	Check(IntengMenus_Find(0x10001) == quit && IntengMenus_Find(0) == nullptr && IntengMenus_Find(-1) == nullptr && IntengMenus_Find(0x7FFFFFFF) == nullptr,
		"an item is found by its number, and a number no item has finds none");
}

// -screen <name> (a command line is hostile input): the exact name of a screen opens that screen, and anything else is refused
// with the allowed names, and no screen is picked
static void TestTheScreenWord()
{
	size_t screen = 99999;
	std::string why;
	bool track = IntengMenus_ScreenFromCommandWord(L"Track Editing", &screen, &why);

	Check(track && screen < kIntengScreenCount && strcmp(kIntengScreens[screen].table, "0x5e6e98") == 0, "a screen's exact name picks that screen (Track Editing is inteng's table 0x5e6e98)");

	bool every = true;

	for (size_t s = 0; s < kIntengScreenCount; s++)
	{
		std::wstring wide(kIntengScreens[s].name, kIntengScreens[s].name + strlen(kIntengScreens[s].name));
		size_t found = 99999;

		every = every && IntengMenus_ScreenFromCommandWord(wide.c_str(), &found, nullptr) && strcmp(kIntengScreens[found].name, kIntengScreens[s].name) == 0;
	}

	Check(every, "every screen's own name is accepted, and finds a screen of that name");

	wchar_t const *const bad[] = { L"track editing", L"Track Editing ", L" Track Editing", L"Track  Editing", L"Track Editin", L"Track Editing\n", L"Track Editing\xe9", L"Track\x01" L"Editing", L"", L"0x5e6e98", L"..\\Track Editing", L"Construction; Track Editing" };
	bool allRefused = true;

	for (wchar_t const *word : bad)
	{
		size_t picked = 424242;
		std::string said;

		allRefused = allRefused && !IntengMenus_ScreenFromCommandWord(word, &picked, &said) && picked == 424242 && said.find("Track Editing") != std::string::npos
			&& said.find("Construction") != std::string::npos;
	}

	Check(allRefused, "a wrong case, a space more or less, a part of a name, a control letter, a letter beyond ASCII, a table address, a path and two names at once are all refused, naming the allowed screens, and pick nothing");

	size_t untouched = 7;
	std::wstring tooLong(65, L'T');

	Check(!IntengMenus_ScreenFromCommandWord(nullptr, &untouched, &why) && !IntengMenus_ScreenFromCommandWord(tooLong.c_str(), &untouched, &why) && untouched == 7,
		"no word and a word of 65 letters are refused, and the answer is left alone");
	Check(!IntengMenus_ScreenFromCommandWord(L"nothing", &untouched, nullptr) && untouched == 7, "a refusal with no place to say why is still a refusal");
}

// The code-built screens (inteng's Strategy, Path, Waypoint, Texture Map and Hierarchy menus, read from the code that registers them): the pages that are
// live for the game kind inteng runs as, the two bars, inteng's own command numbers, and the item numbers (so a click names one item) all different
static const IntengScreen *Built(const char *name)
{
	for (size_t s = 0; s < kIntengScreenCount; s++)
	{
		if (strcmp(kIntengScreens[s].name, name) == 0)
		{
			return &kIntengScreens[s];
		}
	}

	return nullptr;
}

static void TestTheBuiltScreens()
{
	struct Want
	{
		const char *name;
		size_t pages, firstBar, secondBar;
	};

	// pages live for game kind 0, the titles on the first bar and on the second (row 2, page 0)
	const Want wants[] = { { "Strategy Data", 6, 4, 8 }, { "Path", 2, 2, 6 }, { "Waypoint", 8, 3, 3 }, { "Texture Map", 7, 6, 11 }, { "Hierarchy", 2, 7, 7 }, { "Track Editing", 13, 3, 0 } };
	bool counts = true, numbers = true, inBar = true;

	for (const Want &want : wants)
	{
		const IntengScreen *screen = Built(want.name);

		counts = counts && screen && screen->pageCount == want.pages && screen->count == want.firstBar && screen->secondRowCount == want.secondBar;

		if (!screen)
		{
			continue;
		}

		std::string seen;

		for (size_t p = 0; p < screen->pageCount; p++)
		{
			for (size_t m = 0; m < screen->pages[p].count; m++)
			{
				const IntengMenu &menu = screen->pages[p].menus[m];

				inBar = inBar && m < ui::kMenuMostMenus && menu.count <= ui::kMenuMostItems;

				for (size_t i = 0; i < menu.count; i++)
				{
					char text[16];

					_snprintf_s(text, sizeof(text), _TRUNCATE, "%08x,", (unsigned)menu.items[i].action);
					numbers = numbers && seen.find(text) == std::string::npos && menu.items[i].action > 0;
					seen += text;
				}
			}
		}
	}

	Check(counts, "Strategy Data, Path, Waypoint, Texture Map, Hierarchy and Track Editing (13 pages on its table) have the pages and the bars inteng registers (game kind 0)");
	Check(numbers, "no two items of a code-built screen have the same number, across all its pages");
	Check(inBar, "every page of a code-built screen fits the menu bar's limits");

	// inteng's own command numbers and words: Strategy Data's second bar has Delete Strategy as inteng's command 0xc (it WORKS now, Frost's 97e64b9: no tag, its work is the strategy command)
	const IntengScreen *strategy = Built("Strategy Data");
	bool deleteStrategy = false, exitWorks = false;

	for (size_t m = 0; strategy && m < strategy->secondRowCount; m++)
	{
		for (size_t i = 0; i < strategy->secondRow[m].count; i++)
		{
			const IntengItem &item = strategy->secondRow[m].items[i];

			deleteStrategy = deleteStrategy || (item.command == 0xc && strcmp(item.name, "Delete Strategy") == 0 && item.tag == IntengTag::None && item.work == IntengWork::Strategy);
		}
	}

	for (size_t m = 0; strategy && m < strategy->count; m++)
	{
		for (size_t i = 0; i < strategy->menus[m].count; i++)
		{
			exitWorks = exitWorks || (strategy->menus[m].items[i].command == 0x5 && (strategy->menus[m].items[i].work == IntengWork::ToHub || strategy->menus[m].items[i].work == IntengWork::ExitMode));
		}
	}

	Check(deleteStrategy, "Strategy Data's second bar has Delete Strategy under inteng's own command number 0xc, and it works (no tag, the strategy command)");
	Check(exitWorks, "Strategy Data's Exit is inteng's command 0x5 and goes back to the hub");
}

int main()
{
	setvbuf(stdout, NULL, _IONBF, 0);

	TestTheScreens();
	TestTheTablesAreInteng();
	TestEveryItemWorksOrSaysWhy();
	TestTheBuiltScreens();
	TestTheScreenWord();

	printf("%s\n", checksFailed ? "SOME CHECKS FAILED" : "All checks passed");
	return checksFailed ? 1 : 0;
}
